host.replaceChildren();
host.classList.add("pb-canvas");
host.tabIndex = 0;

const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.classList.add("pb-wires");
svg.setAttribute("aria-hidden", "true");

const defs = document.createElementNS("http://www.w3.org/2000/svg", "defs");
defs.innerHTML = "";
const marker = document.createElementNS("http://www.w3.org/2000/svg", "marker");
marker.setAttribute("id", "pb-arrow");
marker.setAttribute("viewBox", "0 0 10 10");
marker.setAttribute("refX", "9");
marker.setAttribute("refY", "5");
marker.setAttribute("markerWidth", "6");
marker.setAttribute("markerHeight", "6");
marker.setAttribute("orient", "auto-start-reverse");
const arrowPath = document.createElementNS("http://www.w3.org/2000/svg", "path");
arrowPath.setAttribute("d", "M 0 0 L 10 5 L 0 10 z");
arrowPath.setAttribute("fill", "currentColor");
marker.append(arrowPath);
defs.append(marker);
svg.append(defs);

const wireLayer = document.createElementNS("http://www.w3.org/2000/svg", "g");
svg.append(wireLayer);

const nodeLayer = document.createElement("div");
nodeLayer.className = "pb-nodes";

const viewport = document.createElement("div");
viewport.className = "pb-viewport";
viewport.append(svg, nodeLayer);
host.append(viewport);

const state = {
  host, viewport, svg, wireLayer, nodeLayer, callbacks,
  pan: { x: 0, y: 0 }, zoom: 1,
  selection: new Set(),
  dragging: null,
  linking: null,
  model: null,
  palette: null,
  problems: [],
};

attachPointerHandlers(state);
attachKeyHandlers(state);
return state;

const { paletteEntry } = globalThis.SOAR;

state.model = model;
state.palette = palette;
state.problems = problems || [];

const worst = new Map();
for (const problem of state.problems) {
  if (!problem.node) continue;
  const rank = { error: 3, warning: 2, info: 1 };
  if ((rank[problem.severity] || 0) > (rank[worst.get(problem.node)] || 0)) {
    worst.set(problem.node, problem.severity);
  }
}

state.viewport.style.transform =
  `translate(${state.pan.x}px, ${state.pan.y}px) scale(${state.zoom})`;

state.nodeLayer.replaceChildren();
const geometry = new Map();

for (const node of model.nodes) {
  const entry = paletteEntry(node, palette);
  const element = renderNode(state, node, entry, worst.get(node.id));
  state.nodeLayer.append(element);
  geometry.set(node.id, element);
}

// Measure after layout so wires attach to the real port positions rather
// than to an assumed node height - node bodies grow with their config.
state.wireLayer.replaceChildren();
for (const edge of model.edges) {
  const path = renderWire(state, edge, geometry);
  if (path) state.wireLayer.append(path);
}

const bounds = contentBounds(model);
state.svg.setAttribute("width", String(bounds.width));
state.svg.setAttribute("height", String(bounds.height));

const element = document.createElement("article");
element.className = "pb-node";
element.dataset.nodeId = node.id;
element.dataset.kind = node.kind;
element.dataset.accent = entry?.accent || "neutral";
element.style.left = `${node.x}px`;
element.style.top = `${node.y}px`;
element.tabIndex = 0;
if (state.selection.has(node.id)) element.classList.add("is-selected");
if (severity) element.dataset.problem = severity;

const header = document.createElement("header");
const icon = document.createElement("span");
icon.className = "pb-icon";
icon.textContent = entry?.icon || "\u25cb";
const title = document.createElement("span");
title.className = "pb-title";
title.textContent = node.label || entry?.label || node.kind;
header.append(icon, title);

if (entry?.effect === "mutating") {
  const badge = document.createElement("span");
  badge.className = `pb-badge risk-${entry.risk_level}`;
  badge.textContent = entry.risk_level.toUpperCase();
  badge.title = "This step changes the estate";
  header.append(badge);
}
if (entry?.requires_approval) {
  const badge = document.createElement("span");
  badge.className = "pb-badge approval";
  badge.textContent = "APPROVAL";
  badge.title = "A human must approve this before it runs";
  header.append(badge);
}

const body = document.createElement("div");
body.className = "pb-body";
body.textContent = summarise(node, entry);

element.append(header, body);

if (node.kind === "response" && entry?.coverage) {
  const coverage = document.createElement("div");
  coverage.className = "pb-coverage";
  coverage.dataset.level = entry.coverage.percent >= 99 ? "full"
    : entry.coverage.percent > 0 ? "partial" : "none";
  coverage.textContent =
    `${entry.coverage.percent}% of hosts \u00b7 ` +
    `${entry.coverage.capable_connectors.join(", ") || "no EDR"}`;
  coverage.title = Object.entries(entry.coverage.semantics || {})
    .map(([name, detail]) => `${name}: ${detail.semantics || detail.command}`)
    .join("\n") || "No configured EDR implements this action";
  element.append(coverage);
}

if (node.retry?.max) {
  const retry = document.createElement("div");
  retry.className = "pb-meta";
  retry.textContent = `retry \u00d7${node.retry.max}`;
  element.append(retry);
}

const ports = document.createElement("footer");
ports.className = "pb-ports";
for (const port of entry?.ports || ["next"]) {
  const handle = document.createElement("button");
  handle.type = "button";
  handle.className = "pb-port";
  handle.dataset.port = port;
  handle.dataset.nodeId = node.id;
  handle.textContent = port.replace(/^on_/, "").replace(/_/g, " ");
  handle.title = `Drag from here to connect the ${port} branch`;
  ports.append(handle);
}
element.append(ports);

const inlet = document.createElement("div");
inlet.className = "pb-inlet";
inlet.dataset.nodeId = node.id;
element.append(inlet);

return element;

switch (node.kind) {
  case "start": return "Execution begins here";
  case "end": return `Outcome: ${node.settings?.outcome || "succeeded"}`;
  case "condition": return node.config?.expression || "no condition set";
  case "switch": return `on ${node.config?.subject || "?"}`;
  case "for_each":
    return `each ${node.config?.as || "item"} of ${node.config?.items || "?"}` +
           ` (max ${node.config?.max_iterations ?? "?"})`;
  case "while": return node.config?.expression || "no condition set";
  case "parallel": return `join: ${node.config?.join || "all"}`;
  case "delay": return `wait ${node.config?.seconds ?? "?"}s`;
  case "approval":
    return node.config?.summary || node.config?.action_key || "approval required";
  case "task": return node.config?.title || "human task";
  case "ai": return `${node.config?.action || "?"} \u00b7 ${node.config?.role || "fast"}`;
  case "script": return `${node.config?.trust_level || "untrusted"} python, sandboxed`;
  case "sub_playbook": return node.playbook || "no playbook selected";
  case "response":
    return `${node.action || "?"} \u2192 ${node.config?.target || "no target"}`;
  case "command": return node.command || "no command selected";
  case "http": return `${node.config?.method || "GET"} ${node.config?.url || ""}`;
  case "set_var": return `${node.config?.name || "?"} = ${node.config?.value || "?"}`;
  default: return entry?.doc?.split(".")[0] || node.kind;
}

const fromElement = geometry.get(edge.from);
const toElement = geometry.get(edge.to);
if (!fromElement || !toElement) return null;

const port = fromElement.querySelector(`.pb-port[data-port="${edge.port}"]`)
  || fromElement.querySelector(".pb-port");
if (!port) return null;

const from = portCentre(state, port);
const to = inletCentre(state, toElement);
const dx = Math.max(60, Math.abs(to.x - from.x) * 0.5);

const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
path.setAttribute("d",
  `M ${from.x} ${from.y} C ${from.x + dx} ${from.y}, ${to.x - dx} ${to.y}, ${to.x} ${to.y}`);
path.setAttribute("class", `pb-wire port-${edge.port}`);
path.setAttribute("marker-end", "url(#pb-arrow)");
path.dataset.edgeId = edge.id;
path.addEventListener("click", (event) => {
  event.stopPropagation();
  state.callbacks.onSelectEdge?.(edge.id);
});

if (edge.label) {
  path.setAttribute("aria-label", edge.label);
  const title = document.createElementNS("http://www.w3.org/2000/svg", "title");
  title.textContent = `${edge.port}: ${edge.label}`;
  path.append(title);
}
return path;

const node = port.closest(".pb-node");
const left = parseFloat(node.style.left) || 0;
const top = parseFloat(node.style.top) || 0;

// Accumulated up to the node rather than read off the port, because
// offsetLeft is relative to the offsetParent and the outlet strip is
// positioned - so it IS the offsetParent, and a single offsetLeft
// leaves out the strip.
let dx = 0;
let dy = 0;
let walk = port;
while (walk && walk !== node) {
  dx += walk.offsetLeft;
  dy += walk.offsetTop;
  walk = walk.offsetParent;
}

return {
  // The right-hand edge of the chip: control leaves a node there.
  x: left + dx + port.offsetWidth,
  y: top + dy + port.offsetHeight / 2,
};

const left = parseFloat(element.style.left) || 0;
const top = parseFloat(element.style.top) || 0;
return { x: left, y: top + Math.min(28, element.offsetHeight / 2) };

let width = 1200;
let height = 700;
for (const node of model.nodes) {
  width = Math.max(width, node.x + 400);
  height = Math.max(height, node.y + 300);
}
return { width, height };

const toCanvas = (event) => {
  const rect = state.host.getBoundingClientRect();
  return {
    x: (event.clientX - rect.left - state.pan.x) / state.zoom,
    y: (event.clientY - rect.top - state.pan.y) / state.zoom,
  };
};

state.host.addEventListener("pointerdown", (event) => {
  const port = event.target.closest(".pb-port");
  const node = event.target.closest(".pb-node");

  if (port) {
    event.preventDefault();
    event.stopPropagation();
    state.linking = { from: port.dataset.nodeId, port: port.dataset.port,
                      at: toCanvas(event) };
    state.host.setPointerCapture(event.pointerId);
    return;
  }

  if (node) {
    const id = node.dataset.nodeId;
    if (!event.shiftKey && !state.selection.has(id)) state.selection.clear();
    state.selection.add(id);
    state.callbacks.onSelect?.([...state.selection]);

    const origin = toCanvas(event);
    state.dragging = {
      pointer: origin,
      moved: false,
      offsets: [...state.selection].map((selected) => {
        const target = state.model.nodes.find((n) => n.id === selected);
        return { id: selected, dx: target.x - origin.x, dy: target.y - origin.y };
      }),
    };
    state.host.setPointerCapture(event.pointerId);
    return;
  }

  state.selection.clear();
  state.callbacks.onSelect?.([]);
  state.dragging = { panning: true, from: { x: event.clientX, y: event.clientY },
                     origin: { ...state.pan } };
  state.host.setPointerCapture(event.pointerId);
  state.callbacks.onChange?.({ silent: true });
});

state.host.addEventListener("pointermove", (event) => {
  if (state.linking) {
    state.linking.at = toCanvas(event);
    drawPendingWire(state);
    return;
  }
  if (!state.dragging) return;

  if (state.dragging.panning) {
    state.pan.x = state.dragging.origin.x + (event.clientX - state.dragging.from.x);
    state.pan.y = state.dragging.origin.y + (event.clientY - state.dragging.from.y);
    state.viewport.style.transform =
      `translate(${state.pan.x}px, ${state.pan.y}px) scale(${state.zoom})`;
    return;
  }

  const at = toCanvas(event);
  state.dragging.moved = true;
  for (const offset of state.dragging.offsets) {
    const node = state.model.nodes.find((n) => n.id === offset.id);
    if (!node) continue;
    // Snap to a 20px grid: playbooks that line up are playbooks people read.
    node.x = Math.round((at.x + offset.dx) / 20) * 20;
    node.y = Math.round((at.y + offset.dy) / 20) * 20;
  }
  state.callbacks.onChange?.({ silent: true });
});

state.host.addEventListener("pointerup", (event) => {
  if (state.linking) {
    const target = event.target.closest(".pb-node");
    const pending = state.linking;
    state.linking = null;
    clearPendingWire(state);
    if (target && target.dataset.nodeId !== pending.from) {
      state.callbacks.onConnect?.(pending.from, pending.port, target.dataset.nodeId);
    } else if (!target) {
      // Dropping a wire on empty canvas offers to create the node it would
      // have pointed at - the fastest way to build a chain.
      state.callbacks.onDropOnEmpty?.(pending.from, pending.port, pending.at);
    }
    return;
  }
  if (state.dragging && !state.dragging.panning && state.dragging.moved) {
    state.callbacks.onChange?.({ label: "move nodes" });
  }
  state.dragging = null;
});

state.host.addEventListener("wheel", (event) => {
  if (!event.ctrlKey && !event.metaKey) return;
  event.preventDefault();
  const next = Math.min(2, Math.max(0.35, state.zoom * (event.deltaY < 0 ? 1.1 : 0.9)));
  state.zoom = next;
  state.viewport.style.transform =
    `translate(${state.pan.x}px, ${state.pan.y}px) scale(${state.zoom})`;
}, { passive: false });

state.host.addEventListener("dblclick", (event) => {
  const node = event.target.closest(".pb-node");
  if (node) state.callbacks.onOpen?.(node.dataset.nodeId);
});

state.host.addEventListener("dragover", (event) => event.preventDefault());
state.host.addEventListener("drop", (event) => {
  event.preventDefault();
  const payload = event.dataTransfer.getData("application/x-soar-node");
  if (!payload) return;
  state.callbacks.onDropPaletteItem?.(JSON.parse(payload), toCanvas(event));
});

clearPendingWire(state);
const fromElement = state.nodeLayer.querySelector(
  `.pb-node[data-node-id="${state.linking.from}"]`);
if (!fromElement) return;
const port = fromElement.querySelector(
  `.pb-port[data-port="${state.linking.port}"]`);
if (!port) return;

const from = portCentre(state, port);
const to = state.linking.at;
const dx = Math.max(60, Math.abs(to.x - from.x) * 0.5);
const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
path.setAttribute("d",
  `M ${from.x} ${from.y} C ${from.x + dx} ${from.y}, ${to.x - dx} ${to.y}, ${to.x} ${to.y}`);
path.setAttribute("class", "pb-wire is-pending");
path.id = "pb-pending-wire";
state.wireLayer.append(path);

state.host.addEventListener("keydown", (event) => {
  const mod = event.ctrlKey || event.metaKey;

  if (mod && event.key.toLowerCase() === "z") {
    event.preventDefault();
    return event.shiftKey ? state.callbacks.onRedo?.() : state.callbacks.onUndo?.();
  }
  if (mod && event.key.toLowerCase() === "y") {
    event.preventDefault();
    return state.callbacks.onRedo?.();
  }
  if (mod && event.key.toLowerCase() === "s") {
    event.preventDefault();
    return state.callbacks.onSave?.();
  }
  if (mod && event.key.toLowerCase() === "d") {
    event.preventDefault();
    return state.callbacks.onDuplicate?.([...state.selection]);
  }

  if (event.key === "Delete" || event.key === "Backspace") {
    if (!state.selection.size) return;
    event.preventDefault();
    return state.callbacks.onDelete?.([...state.selection]);
  }
  if (event.key === "Escape") {
    state.selection.clear();
    state.callbacks.onSelect?.([]);
    return state.callbacks.onChange?.({ silent: true });
  }
  if (event.key === "f" && !mod) {
    return state.callbacks.onFrame?.();
  }

  const NUDGE = { ArrowLeft: [-20, 0], ArrowRight: [20, 0],
                  ArrowUp: [0, -20], ArrowDown: [0, 20] };
  const delta = NUDGE[event.key];
  if (delta && state.selection.size) {
    event.preventDefault();
    for (const id of state.selection) {
      const node = state.model.nodes.find((n) => n.id === id);
      if (node) { node.x += delta[0]; node.y += delta[1]; }
    }
    state.callbacks.onChange?.({ label: "nudge" });
  }
});

const nodes = state.model?.nodes || [];
if (!nodes.length) return;

const minX = Math.min(...nodes.map((n) => n.x)) - 60;
const minY = Math.min(...nodes.map((n) => n.y)) - 60;
const maxX = Math.max(...nodes.map((n) => n.x)) + 300;
const maxY = Math.max(...nodes.map((n) => n.y)) + 220;

const rect = state.host.getBoundingClientRect();
state.zoom = Math.min(1, Math.max(0.35,
  Math.min(rect.width / (maxX - minX), rect.height / (maxY - minY))));
state.pan.x = -minX * state.zoom + 20;
state.pan.y = -minY * state.zoom + 20;
state.viewport.style.transform =
  `translate(${state.pan.x}px, ${state.pan.y}px) scale(${state.zoom})`;

const depth = new Map([[model.start, 0]]);
const queue = [model.start];
while (queue.length) {
  const current = queue.shift();
  for (const edge of model.edges.filter((e) => e.from === current)) {
    if (depth.has(edge.to)) continue;
    depth.set(edge.to, depth.get(current) + 1);
    queue.push(edge.to);
  }
}

const rows = new Map();
for (const node of model.nodes) {
  const column = depth.get(node.id) ?? 0;
  const row = rows.get(column) || 0;
  node.x = 80 + column * 300;
  node.y = 100 + row * 170;
  rows.set(column, row + 1);
}

globalThis.SOAR = globalThis.SOAR || {};
Object.assign(globalThis.SOAR, {
  createCanvas,
  renderCanvas,
  frame,
  autoLayout,
});
